# each node is a list: [value, left, right]
def insert(node, val):
    if node is None:
        return [val, None, None]
    side = 1 if val < node[0] else 2
    node[side] = insert(node[side], val)
    return node
def contains(node, val):
    while node and node[0] != val:
        node = node[1] if val < node[0] else node[2]
    return node is not None
root = None
for v in [8, 3, 10, 1, 6, 14, 9]:
    root = insert(root, v)
print(contains(root, 6), contains(root, 5))
